def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=3: continue
            # emblem: top stripe, outlined sides and center, with baseline extending across row
            for cc in range(c-2,c+3):
                if 0<=r-2<h and 0<=cc<w: out[r-2][cc]=5
            if 0<=r-1<h: out[r-1][c]=5
            for rr in range(r-1,r+2):
                if 0<=rr<h:
                    for cc in (c-2,c+2):
                        if 0<=cc<w: out[rr][cc]=2
            rr=r+2
            if rr<h:
                for cc in range(w):out[rr][cc]=2
                for cc in range(c-2,c+3):
                    if 0<=cc<w:out[rr][cc]=8
    return out
